from common import *

def extra(aid,suffix,title,paragraphs,refs):
 s=dict(id=aid+'-'+suffix,title=title,paragraphs=paragraphs,sourceIds=refs)
 articles[aid]['patch']['sections'].append(s)
 return s

aid='ref-histoire-culture'
setarticle(aid,'Comment raconter l’histoire du chanvre sans confondre récit, objet et preuve ? Un écrivain décrit une soirée, un archéologue examine une tombe et un musée identifie un matériau : chacun répond à une question différente.',[
['Le Club des Hachichins est le titre d’un récit de Théophile Gautier, publié le 1er février 1846 dans le tome 13 de la Revue des Deux Mondes. Il situe une soirée à l’hôtel Pimodan, aujourd’hui hôtel de Lauzun, sur l’île Saint-Louis à Paris. Le narrateur parle de séances mensuelles : c’est ce que raconte le texte, pas un calendrier complet des réunions.','Le peintre Boissard de Boisdenier accueille des rencontres où le médecin Jacques-Joseph Moreau de Tours s’intéresse aux effets du haschisch sur la pensée et les perceptions. En 1845, à Paris, Moreau publie Du hachisch et de l’aliénation mentale : études psychologiques. L’« aliénation mentale » appartient au vocabulaire médical de l’époque. Cette investigation du fonctionnement psychique précède les essais cliniques modernes et leurs méthodes de comparaison.'],
['Le français emprunte le mot « marijuana » au XXe siècle à l’anglais des États-Unis, qui le tient de l’espagnol mexicain. Les formes mexicaines mariguana et marihuana sont attestées avant la diffusion de marijuana par l’anglais. Ce trajet entre langues est mieux connu que l’origine ultime du mot, qui reste incertaine.','Le rapprochement avec les prénoms María Juana est une explication populaire, pas une origine démontrée par les premières attestations. L’histoire d’un nom ne suffit pas non plus à définir une espèce botanique ni la composition chimique d’une plante.'],
['Toutes les toiles bretonnes ne sont pas en chanvre. L’Inventaire distingue les Olonnes de Locronan et les Noyales de Noyal-sur-Vilaine, en chanvre, des crées du Léon et des Bretagnes du Centre-Bretagne, en lin. Pouldavid, Landerneau, Morlaix et Saint-Malo participent aux exportations. Nommer le lieu et la fibre évite de transformer une histoire textile variée en histoire d’un seul matériau.','La Corderie royale de Rochefort est construite en 1666, sous Louis XIV. Les cordages navals peuvent être très longs : la fiche patrimoniale donne un exemple d’environ 195 mètres, qui aide à comprendre les ateliers allongés. Elle associe les Noyales à l’approvisionnement de la Marine royale sous Louis XV.'],
['George Washington cultive du chanvre à Mount Vernon. La documentation du domaine le relie aux cordes, aux fils pour sacs, aux toiles et à la réparation des filets de senne, de grands filets employés sur le Potomac. Elle rappelle aussi des usages de l’huile des graines dans les peintures, les vernis et les savons. Cela documente des matériaux ; cela ne prouve pas une consommation intoxicante de Washington.','L’exemplaire signé de la Déclaration d’indépendance américaine est sur parchemin, une peau animale préparée pour écrire, selon les Archives nationales. Le Congrès ordonne ce support le 19 juillet 1776 ; le journal du 2 août mentionne les signatures. Cela concerne cet exemplaire précis, sans déterminer la matière de tous les brouillons. De même, l’existence ancienne de papier de fibres végétales ne prouve pas qu’un exemplaire de Gutenberg soit en chanvre : il faudrait une analyse ou un catalogue propre à cet objet.'],
['À Yanghai, dans le bassin de Turpan au Xinjiang, la tombe M90 contient un homme âgé d’environ 45 ans, une harpe appelée kongou ou konghou, ainsi que du cannabis dans un panier de cuir et un bol de bois. L’étude rapporte 789 g de matière végétale et discute une datation corrigée d’environ 2700 ans BP. BP signifie « avant le présent », mais son point de référence conventionnel est 1950, pas l’année où nous lisons le texte.','Le climat très aride, les tombes profondes et les sols alcalins, chimiquement à l’opposé de sols acides, favorisent la conservation. La présence des plantes et des objets est une observation. Un emploi médicinal ou divinatoire est une interprétation ; ces objets ne démontrent ni le statut exact du défunt ni la manière dont le cannabis aurait été administré.']],
'Comment une trace devient-elle une preuve historique ?', ['témoignage','attestation','parchemin','datation BP','interprétation archéologique'], 'Identifier le support de l’exemplaire signé ne renseigne pas automatiquement tous les brouillons.', ['Un récit donne-t-il la liste complète des participants ?','Des graines prouvent-elles à elles seules un usage intoxicant ?'], ['Un récit de soirée et une recherche médicale du XIXe siècle','Le voyage d’un mot entre les langues','Des toiles et des cordages : identifier la fibre','Washington et la matière des documents','Yanghai : distinguer ce qui est trouvé de ce qui est interprété'])
a=articles[aid]
a['patch']['sections'][0]['sourceIds']=['qh-culture-gautier','qh-culture-bnf','qh-culture-institut','qh-culture-moreau']
a['patch']['sections'][2]['sourceIds']=['qh-culture-bretagne','qh-culture-bretagne-toiles','qh-culture-pci']
a['patch']['sections'][4]['sourceIds']=['qh-culture-yanghai']
extra(aid,'temoins','Des participants cités et des écrivains, pas une liste de membres',[
'La présentation d’une recherche historique situe les rencontres de l’hôtel Pimodan entre 1845 et 1849 et critique l’image d’une société secrète permanente. Michel Caire cite Aglaé et Marix, ainsi qu’une lettre envoyée par Balzac depuis Passy après une soirée. Ces témoignages particuliers ne prouvent pas une présence régulière de toutes ces personnes. Il décrit aussi une expérience en 1840 chez le vicomte Ajasson de Grandsagne, sans Moreau : toutes les réunions parisiennes de cette période ne sont donc pas le même « Club ».',
'Baudelaire publie Les Paradis artificiels, opium et haschisch en 1860. Le livre réunit Le Poème du haschisch et Un mangeur d’opium, où il présente et traduit partiellement les Confessions de Thomas de Quincey. Aux États-Unis, Fitz Hugh Ludlow publie The Hasheesh Eater en 1857, à New York chez Harper & Bros. Ces œuvres racontent et représentent des expériences ; leur célébrité ne prouve ni une pratique universelle ni une absence de risques.'],['qh-culture-research','qh-culture-tours','qh-culture-baudelaire','qh-culture-ludlow'])
extra(aid,'fibres','De la tige au fil : ce que font les outils',[
'Le teillage consiste à séparer les fibres de la partie ligneuse, le bois de la tige. Dans les pratiques manuelles décrites, la braie ou broye casse cette partie dure ; la pesselle, une lame de bois, assouplit les fibres et enlève des résidus ; les peignes métalliques achèvent la séparation. La filasse rassemble les fibres longues à filer. L’étoupe réunit les fibres courtes, utiles notamment aux joints et au calfatage, l’obturation des interstices d’un bateau pour limiter les entrées d’eau.',
'Les chanvriers et tisserands de Peillac se retrouvent jusqu’en 1940 à la foire de Redon, dite Teillouse : le lieu de la foire est Redon. La fiche patrimoniale rattache aussi Canebière à un mot provençal désignant une chanvrière, un terrain cultivé en chanvre. Elle évoque un essor sous Charlemagne vers l’an 800 ; ce repère reste attribué à ce récit secondaire, sans mesure établie ici à partir d’un texte carolingien.'],['qh-culture-bretagne-fibres','qh-culture-bretagne-process','qh-culture-pci'])
extra(aid,'jirzankal','Jirzankal : que racontent les résidus d’un brasero ?',[
'Jirzankal, aussi appelé cimetière de Quman, se trouve dans le Pamir oriental. L’étude de 2019 examine des sépultures d’environ 2500 ans, vers 500 avant notre ère. La zone B est à 3061 m d’altitude. Dix braseros en bois provenant de huit tombes contiennent des pierres portant des traces de chauffe.',
'Les chercheurs comparent des résidus intérieurs à des témoins extérieurs. Ils trouvent du CBN, un produit de transformation du THC, dans neuf braseros et sur deux pierres. Cela soutient l’hypothèse de cannabis brûlé dans un contexte funéraire. Cela ne mesure pas la teneur initiale en THC, ni ce que les participants ont ressenti.',
'Hérodote décrit au livre IV des Histoires le chanvre et des pratiques scythes liées aux funérailles : c’est un témoignage littéraire ancien. L’article de Jirzankal compare aussi Pazyryk, où la tombe 2 associe un petit cadre de tente en bois, des récipients en cuivre, des pierres chauffées et du chanvre. Une comparaison rapportée par cet article ne prouve pas que tous les rites étaient identiques.'],['qh-culture-jirzankal','qh-culture-herodotus'])
extra(aid,'graines','Des graines et des textiles répondent à d’autres questions',[
'À Haimenkou, au Yunnan, les fouilles de 2008 ont livré plus de 800 graines de chanvre. Leur contexte et leurs dimensions peuvent renseigner l’histoire des plantes ; ils ne révèlent pas automatiquement un usage intoxicant. La discussion de cette étude cite des textiles identifiés comme chanvre à Ban Don Ta Phet, en Thaïlande, vers 400 avant notre ère : cette information est rapportée par cette discussion.',
'Une synthèse archéobotanique de 2025, qui rassemble des travaux sur les plantes anciennes, cite des graines d’Oki-no-shima au Japon, associées au Jōmon initial et datées de 6000 à 5220 ans calibrés BP. « Calibrés » indique que les datations ont été corrigées à l’aide de références ; BP garde 1950 comme point de départ. Graines, fibres, pollen et traces chimiques ne répondent pas à la même question. Certains pollens de Cannabis et de Humulus, le houblon, sont même difficiles à distinguer. Aucun de ces indices ne désigne à lui seul un lieu unique de domestication ni la première consommation de toute l’humanité.'],['qh-culture-haimenkou','qh-culture-archaeology-review'])
# Grouper les passages dans l’ordre de lecture, sans supprimer d’ancienne ancre.
sections=a['patch']['sections'];a['patch']['sections']=[sections[i] for i in [0,5,1,2,6,3,4,7,8]]
diagram(aid,'La question dépend de la trace',[('Un récit','Gautier raconte une soirée, sans tenir un registre complet.'),('Un objet','Le support signé de la Déclaration est identifié comme parchemin.'),('Une plante conservée','Yanghai documente des restes et leur contexte.'),('Un résidu','Jirzankal soutient une interprétation de combustion.')],'Le récit, le matériau et la trace chimique n’apportent pas la même preuve.',after=aid+'-graines',kind='comparison')

aid='ref-histoire-politiques'
setarticle(aid,'Une taxe, un classement international et une loi nationale ne changent pas les mêmes règles. Suivre l’histoire politique du cannabis demande donc de préciser le pays, le mécanisme juridique et la date à laquelle il produit ses effets.',[
['Aux États-Unis, le Marihuana Tax Act du 2 août 1937 utilise des taxes, un enregistrement et des obligations sur les transferts. Cette combinaison impose de fortes contraintes sans se réduire à une phrase interdisant toute plante. La définition de marihuana exclut notamment les tiges mûres, leurs fibres et certains produits des graines : les usages textiles ne se confondent donc pas avec tous les usages visés.',
'Le Controlled Substances Act de 1970, ou CSA, organise cinq catégories de substances contrôlées appelées schedules. Le Congrès place initialement la marijuana au Schedule I. Un projet de reclassement publié par la DEA en 2024 rappelle cette étape historique ; l’existence d’un projet ne prouve pas qu’il est entré en vigueur. Ces catégories américaines ne sont pas les tableaux de l’ONU.'],
['Un traité est un engagement international entre États. Il faut distinguer sa négociation, sa signature et son entrée en vigueur, le moment où il produit ses effets juridiques selon ses conditions. La Convention internationale de l’opium est signée à Genève le 19 février 1925, avant les trois instruments souvent cités aujourd’hui.',
'La Convention unique sur les stupéfiants est élaborée à New York, lors de la conférence du 24 janvier au 25 mars 1961. L’instrument est daté du 30 mars 1961 et entre en vigueur le 13 décembre 1964 ; le Protocole de 1972 l’amende, c’est-à-dire le modifie. La Convention sur les substances psychotropes de 1971 résulte d’une conférence à Vienne du 11 janvier au 21 février. Celle de 1988 porte explicitement sur le trafic illicite ; sa conférence a lieu à Vienne du 25 novembre au 20 décembre 1988. Ces textes couvrent des objets différents et ne sont pas trois lois nationales identiques.'],
['En Uruguay, la loi 19.172 est promulguée le 20 décembre 2013, puis publiée le 7 janvier 2014. La promulgation confirme officiellement la loi ; la publication la rend publique dans le support prévu. Ces étapes et la mise en place effective d’un système peuvent être séparées dans le temps.',
'L’article premier met en avant la protection et la promotion de la santé, avec la réduction des risques et des dommages. Les articles 17 et 18 créent l’IRCCA, l’Instituto de Regulación y Control del Cannabis, et lui donnent des missions de régulation et de contrôle. Il s’agit d’organiser un cadre public, pas de supprimer toute règle.']],
'Pourquoi une date de réforme ne suffit-elle pas à connaître ce qui devient permis ?', ['taxation','schedule','traité','entrée en vigueur','amendement','promulgation','régulation'], 'Une loi peut être promulguée en décembre et publiée en janvier, sans que toutes les étapes du marché se produisent le même jour.', ['Retirer un produit d’un tableau signifie-t-il le retirer de tous les autres ?','Un accès médical national est-il une légalisation mondiale ?'], ['États-Unis : taxer puis classer les substances','Trois conventions et des dates de nature différente','Uruguay : de la loi à un organisme de régulation'])
a=articles[aid];a['patch']['sections'][0]['sourceIds']=['qh-hist-statutes','qh-hist-csa','qh-hist-csa-policy'];a['patch']['sections'][2]['sourceIds']=['qh-hist-uruguay','qh-hist-uruguay-impo']
extra(aid,'enquetes','Les enquêtes et les politiques agricoles ne sont pas des lois identiques',[
'Le Federal Bureau of Narcotics est créé en 1930, avec Harry J. Anslinger comme premier commissaire. Pendant la Seconde Guerre mondiale, le catalogue de l’USDA situe vers 1942 le film Hemp for Victory, consacré au chanvre pour les besoins en fibres. Une politique de production de fibres et un contrôle des drogues peuvent donc coexister.',
'Une résolution coloniale de 1895 indique que l’Indian Hemp Drugs Commission a un champ couvrant l’Inde au-delà du seul Bengale ; elle mentionne un rapport reçu en épreuves en août 1894. À New York, le rapport LaGuardia de 1944 sépare la supervision financière de l’étude sociologique, confiée à la New York Academy of Medicine, de l’étude clinique, relevant du Research Council du Department of Hospitals. Ces documents renseignent des enquêtes historiques ; leurs méthodes ne remplacent pas les comparaisons médicales actuelles.',
'En 1972 paraît Marihuana: A Signal of Misunderstanding, rapport de la Commission nationale américaine sur la marijuana et l’abus des drogues, présidée par Raymond P. Shafer. Le catalogue confirme le titre, l’année et l’attribution, sans établir à lui seul chaque recommandation ni le jour exact de remise. En Californie, la Proposition 215, Compassionate Use Act of 1996, concerne un cadre médical : ce n’est pas une légalisation générale fédérale.'],['qh-hist-anslinger','qh-hist-hemp-victory','qh-hist-hemp-commission','qh-hist-laguardia','qh-hist-shafer-wellcome','qh-hist-prop215'])
extra(aid,'vote2020','Le vote de 2020 retire un classement, pas tous les contrôles',[
'Le 2 décembre 2020, la Commission des stupéfiants de l’ONU adopte la décision 63/17 par 27 voix pour, 25 contre et une abstention. Cannabis et résine de cannabis quittent le tableau IV de la Convention de 1961, mais restent dans son tableau I. Le mot français est « tableau » ; ces numéros appartiennent à cette convention.',
'Une substance peut figurer dans plusieurs listes à la fois. En retirer une inscription ne supprime donc pas automatiquement l’autre. Ce vote ne retire pas le cannabis de tout contrôle international et ne légalise pas mondialement les usages récréatifs.'],['qh-hist-un-2020'])
extra(aid,'canada','Canada : une entrée en vigueur avec des règles de marché',[
'La Loi sur le cannabis entre en vigueur au Canada le 17 octobre 2018. Le document gouvernemental décrit un encadrement de la production, de la distribution, de la vente, des importations et exportations, ainsi que de la possession pour les adultes admissibles, avec des responsabilités réparties.',
'Réguler un marché, c’est organiser des permissions et des obligations. Cela se distingue d’un accès médical, d’une dépénalisation, qui retire certaines sanctions pénales, ou d’un changement de classement dans un traité. Ces repères historiques ne donnent pas les permissions individuelles actuelles : celles-ci dépendent du lieu et de textes susceptibles de changer.'],['qh-hist-canada'])
sections=a['patch']['sections'];a['patch']['sections']=[sections[i] for i in [0,3,1,4,2,5]]
diagram(aid,'Des changements qui n’agissent pas au même niveau',[('1937, États-Unis','Taxation et obligations de transfert.'),('1961 puis 1964, ONU','Convention, puis entrée en vigueur ; modification en 1972.'),('1970, États-Unis','Classement national en cinq schedules.'),('2013 puis 2014, Uruguay','Promulgation puis publication de la loi 19.172.'),('2018, Canada','Entrée en vigueur d’un cadre national le 17 octobre.'),('2020, ONU','Sortie du tableau IV, maintien au tableau I.')],'Les dates racontent plusieurs mécanismes ; elles ne donnent pas une permission universelle.',after=aid+'-canada',kind='timeline')

from history_quiz import explanations as history_explanations
for q in quiz.values():
 if q.get('articleId') in {'ref-histoire-culture','ref-histoire-politiques'}:
  assert q['id'] in history_explanations,q['id']
  q['explanation']=history_explanations[q['id']]
  # Correction grammaticale, sans changement de réponse ni d’indice.
  q['prompt']=q['prompt'].replace('de l’tableau','du tableau')
  q['options']=[o.replace('de l’tableau','du tableau') for o in q['options']]
write('history-01.json')
